import "./leaflet.css";
import "leaflet/dist/leaflet.css";

import { supabase } from "./supabaseClient";

import {
  MapContainer,
  TileLayer,
  Marker,
  Popup,
  useMapEvents,
} from "react-leaflet";
import MarkerClusterGroup from "react-leaflet-cluster";

import { Icon, divIcon, point } from "leaflet";
import { useState, useEffect } from "react";

// Create default icon without file requires
const createIconWithURL = (url, size = [30, 30]) => {
  return new Icon({
    iconUrl: url,
    iconSize: size,
    shadowUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png",
  });
};

const customIcon2 = new Icon({
  iconUrl: "https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-blue.png",
  iconSize: [25, 41],
  shadowUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png",
});

const createClusterCustomIcon = function (cluster) {
  return new divIcon({
    html: `<span class="cluster-icon">${cluster.getChildCount()}</span>`,

    className: "custom-marker-cluster",
    iconSize: point(33, 33, true),
  });
};

const defaultMarkers = [
  {
    geocode: [57.042928, 9.918538],
    popUp: "AALBORG KENNEDY",
  },
  {
    geocode: [57.051588, 9.916695],
    popUp: "AALBORG VESTERBRO",
  },
];

const locationIcon = new Icon({
  iconUrl: "https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-red.png",
  iconSize: [25, 41],
  shadowUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png",
});

function LocationMarker() {
  const [position, setPosition] = useState(null);
  const [hasLocated, setHasLocated] = useState(false);

  const map = useMapEvents({
    locationfound(e) {
      setPosition(e.latlng);

      if (!hasLocated) {
        try {
          map.setView(e.latlng, 13.4);
          setHasLocated(true);
        } catch (err) {
          console.error("Error setting map view:", err);
        }
      }
    },
    locationerror(e) {
      console.error("Geolocation error:", e);
    },
  });

  useEffect(() => {
    try {
      map.locate({
        setView: false,
      });
    } catch (err) {
      console.error("Error calling map.locate:", err);
    }
  }, [map]);

  if (!position) {
    return null;
  }

  return (
    <Marker position={position} icon={locationIcon}>
      <Popup>Du står lige her!</Popup>
    </Marker>
  );
}

export default function App() {
  const [markers, setMarkers] = useState(defaultMarkers);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchMarkers = async () => {
      try {
        setLoading(true);
        const { data, error } = await supabase
          .from("Vejbod")
          .select("*");

        if (error) {
          console.error("Supabase error:", error);
          setError(error.message);
          setMarkers(defaultMarkers);
        } else if (data && data.length > 0) {
          // Log the first record to see the actual field names
          console.log("First Vejbod record:", data[0]);
          
          // Transform Supabase data to match marker format
          // Check if data has latitude/longitude or other field names
          const transformedMarkers = data.map((item) => {
            const lat = item.latitude || item.lat || item.Latitude;
            const lng = item.longitude || item.lng || item.lon || item.Longitude;
            const name = item.name || item.Name || item.vejbod_name || "Vejbod";
            
            if (lat !== undefined && lng !== undefined) {
              return {
                geocode: [parseFloat(lat), parseFloat(lng)],
                popUp: name,
              };
            }
            return null;
          }).filter(m => m !== null);
          
          if (transformedMarkers.length > 0) {
            setMarkers(transformedMarkers);
            console.log("Loaded markers:", transformedMarkers);
          } else {
            console.warn("No valid coordinates found in data");
            setMarkers(defaultMarkers);
          }
        } else {
          console.log("No data returned from Supabase");
          setMarkers(defaultMarkers);
        }
      } catch (err) {
        console.error("Error fetching markers:", err);
        setError(err.message);
        setMarkers(defaultMarkers);
      } finally {
        setLoading(false);
      }
    };

    fetchMarkers();
  }, []);

  return (
    <div>
      {loading && <p>Loading markers...</p>}
      {error && <p style={{ color: "red" }}>Error: {error}</p>}
      <MapContainer center={[57.050028, 9.965567]} zoom={7}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {markers.length > 0 && <LocationMarker />}

        <MarkerClusterGroup
          chunkedLoading
          iconCreateFunction={createClusterCustomIcon}
        >
          {markers.map((marker, index) => (
            marker.geocode && 
            <Marker key={index} position={marker.geocode} icon={customIcon2}>
              <Popup>{marker.popUp}</Popup>
            </Marker>
          ))}
        </MarkerClusterGroup>
      </MapContainer>
    </div>
  );
}

